      "key": "obs_safe_def",
      "facet": "property",
      "statement": "Request methods are considered safe if their defined semantics are essentially read-only; the client does not request, and does not expect, any state change on the origin server as a result of applying a safe method to a target resource.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_impl_side_effects",
      "facet": "mechanism",
      "statement": "An implementation may include behavior that is potentially harmful, not entirely read-only, or causes side effects while invoking a safe method.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_client_accountability",
      "facet": "property",
      "statement": "The client did not request additional behavior (such as side effects) and cannot be held accountable for it.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_safe_methods_list",
      "facet": "term",
      "statement": "GET, HEAD, OPTIONS, and TRACE are defined to be safe request methods.",
      "start_line": 7,
      "end_line": 7
    }
  ],
